import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.Dkj3JE0_.js";const c=JSON.parse('{"title":"CFA 二级计划","description":"","frontmatter":{"title":"CFA 二级计划"},"headers":[],"relativePath":"zh/blogs/CFA/plan.md","filePath":"zh/blogs/CFA/plan.md"}'),n={name:"zh/blogs/CFA/plan.md"};function i(s,t,d,o,h,p){return l(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="cfa-二级学习计划" tabindex="-1">CFA 二级学习计划 <a class="header-anchor" href="#cfa-二级学习计划" aria-label="Permalink to &quot;CFA 二级学习计划&quot;">​</a></h1><blockquote><p><strong>基本假设：</strong> 考试在 <strong>2026 年 11 月 18 日（周三）</strong>。到 <strong>10 月 31 日</strong>为止是冲刺期（每周约 <strong>40 小时</strong>，FSA 优先），学完剩余课程；<strong>11 月 1–16 日</strong>复习并做 <strong>3–4 套模考</strong>；<strong>11 月 17–18 日</strong>只做轻量练习。不要砍掉模考与复盘阶段。</p></blockquote><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><ul><li>在 **10 月 31 日（周五）**前完成所有剩余科目的第一轮学习（权益、固定收益、投资组合管理、公司发行人、另类投资，以及 FSA 和道德的剩余部分）。</li><li>每学完一个模块就做完章末习题；只维护一本精简的公式与错题本，而不是第二本教材。</li><li>完成 <strong>3–4 套限时模考</strong>（日期见下），每套的复盘时间不少于考试时间；每个复习周都先复盘 FSA。</li><li>进入考试周时，没有哪个科目在限时条件下反复崩盘；11 月 17–18 日保证睡眠。</li></ul><h2 id="当前重点-截至-2026-年-10-月-14-日" tabindex="-1">当前重点（截至 2026 年 10 月 14 日） <a class="header-anchor" href="#当前重点-截至-2026-年-10-月-14-日" aria-label="Permalink to &quot;当前重点（截至 2026 年 10 月 14 日）&quot;">​</a></h2><p><strong>已完成（无需第一轮）：</strong> 衍生品、数量方法。</p><p><strong>部分完成：</strong> 经济学还剩约一半。道德进行中——已学完标准 I(C)、I(D)、I(E) 和 II(A)。</p><p><strong>进行中：</strong> FSA 模块 1（公司间投资），学到权益法基础例题（派息后投资账面价值为 118）。落后于理想的“学完 M1 + 开始 M2”日程——到周日前用晚上追赶。</p><p><strong>尚未开始第一轮：</strong> 权益、固定收益、投资组合管理、公司发行人、另类投资。最薄弱的是 FSA。</p><p><strong>下一步：</strong> 做完 M1 章末题 → <strong>M2 员工薪酬</strong> → M3–M6（追赶期间先写提纲也可以）+ 道德剩余部分 + 学完经济学剩下的一半。</p><h2 id="每周节奏-工作日" tabindex="-1">每周节奏（工作日） <a class="header-anchor" href="#每周节奏-工作日" aria-label="Permalink to &quot;每周节奏（工作日）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时段</th><th style="text-align:right;">时间</th><th>内容</th></tr></thead><tbody><tr><td>晚间 CFA</td><td style="text-align:right;">20:00–02:00</td><td>主要的课程学习与练习时段。</td></tr><tr><td>健身</td><td style="text-align:right;">18:00–20:00</td><td>个人时间——不排 CFA。</td></tr><tr><td>周报</td><td style="text-align:right;">周一 08:00–10:00</td><td>工作事务——不排 CFA。</td></tr></tbody></table><p>Animus 测验只在 <strong>02:00</strong> 笔记检查之后或明确的当日收尾时进行——不要在学习中途做。</p><p>CFA 时段内按 <strong>40/60</strong> 分配：阅读不超过 40%；至少 60% 用于回忆、计算和案例题练习。</p><h2 id="冲刺路线" tabindex="-1">冲刺路线 <a class="header-anchor" href="#冲刺路线" aria-label="Permalink to &quot;冲刺路线&quot;">​</a></h2><h3 id="第一阶段——学完课程-10-月-12–31-日-·-每周约-40-小时-·-fsa-优先" tabindex="-1">第一阶段——学完课程（10 月 12–31 日 · 每周约 40 小时 · FSA 优先） <a class="header-anchor" href="#第一阶段——学完课程-10-月-12–31-日-·-每周约-40-小时-·-fsa-优先" aria-label="Permalink to &quot;第一阶段——学完课程（10 月 12–31 日 · 每周约 40 小时 · FSA 优先）&quot;">​</a></h3><h4 id="本周-10-月-13–18-日" tabindex="-1">本周（10 月 13–18 日） <a class="header-anchor" href="#本周-10-月-13–18-日" aria-label="Permalink to &quot;本周（10 月 13–18 日）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>重点</th><th style="text-align:right;">小时</th><th>10 月 18 日（周日）前的目标</th></tr></thead><tbody><tr><td>FSA 深度学习</td><td style="text-align:right;">22–24</td><td>第一轮完成 ≥80–100% + 章末题</td></tr><tr><td>道德剩余部分</td><td style="text-align:right;">6–8</td><td>开始 II(A) 之后的标准</td></tr><tr><td>经济学收尾</td><td style="text-align:right;">3–4</td><td>学完剩下的一半</td></tr></tbody></table><h4 id="_10-月-19–25-日这周" tabindex="-1">10 月 19–25 日这周 <a class="header-anchor" href="#_10-月-19–25-日这周" aria-label="Permalink to &quot;10 月 19–25 日这周&quot;">​</a></h4><ul><li>权益：完整第一轮。</li><li>固定收益：完成第一轮的大部分。</li><li>FSA 巩固：6–8 小时混合练习。</li></ul><h4 id="_10-月-26–31-日这周" tabindex="-1">10 月 26–31 日这周 <a class="header-anchor" href="#_10-月-26–31-日这周" aria-label="Permalink to &quot;10 月 26–31 日这周&quot;">​</a></h4><ul><li>学完固定收益。</li><li>投资组合管理、公司发行人、另类投资。</li><li>道德案例练习。</li><li><strong>10 月 31 日（周五）前学完全部课程。</strong></li></ul><h3 id="第二阶段——复习与模考-11-月-1–16-日" tabindex="-1">第二阶段——复习与模考（11 月 1–16 日） <a class="header-anchor" href="#第二阶段——复习与模考-11-月-1–16-日" aria-label="Permalink to &quot;第二阶段——复习与模考（11 月 1–16 日）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模考</th><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>模考 1</td><td>11 月 1 日（周六）</td><td>完整限时；复盘先看 FSA。</td></tr><tr><td>模考 2</td><td>11 月 8 日（周六）</td><td>完整限时；周中修补最弱的两个科目。</td></tr><tr><td>模考 3</td><td>11 月 12 日（周三）</td><td>完整限时。</td></tr><tr><td>可选模考 4</td><td>11 月 15 日（周六）</td><td>仅在精力和复盘进度允许时做。</td></tr></tbody></table><p>每个复习周：先 FSA，再复习最近一次模考得分最低的科目。重做错题本中的题；每周凭记忆重写一次核心公式表。</p><h3 id="第三阶段——减量-11-月-17–18-日" tabindex="-1">第三阶段——减量（11 月 17–18 日） <a class="header-anchor" href="#第三阶段——减量-11-月-17–18-日" aria-label="Permalink to &quot;第三阶段——减量（11 月 17–18 日）&quot;">​</a></h3><ul><li>只做轻量混合题；不做完整模考。</li><li>道德、公式、反复出现的错误、计算器步骤和考试安排。</li><li>保证睡眠；不再增加新资料。</li></ul><h2 id="每周复盘模板" tabindex="-1">每周复盘模板 <a class="header-anchor" href="#每周复盘模板" aria-label="Permalink to &quot;每周复盘模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>计划 / 完成小时数：</span></span>
<span class="line"><span>FSA / 道德 / 其他科目进度：</span></span>
<span class="line"><span>做题数 / 正确率：</span></span>
<span class="line"><span>最弱科目与错误模式：</span></span>
<span class="line"><span>一个我现在能讲给别人听的概念：</span></span>
<span class="line"><span>下周要做的一个改变：</span></span></code></pre></div><h2 id="接下来七天-10-月-14–20-日" tabindex="-1">接下来七天（10 月 14–20 日） <a class="header-anchor" href="#接下来七天-10-月-14–20-日" aria-label="Permalink to &quot;接下来七天（10 月 14–20 日）&quot;">​</a></h2><ul><li>[ ] 做完 FSA M1 章末题，开始 <strong>M2 员工薪酬</strong>。</li><li>[ ] 推进 FSA M3–M6（追赶期间先写提纲也可以）。</li><li>[ ] 继续学 II(A) 之后的道德标准；本周至少做一组短的道德题。</li><li>[ ] 学完经济学剩下的一半。</li><li>[ ] 达成 18 日（周日）检查点：FSA 第一轮 ≥80–100% + 章末题；道德在推进；经济学收尾。</li><li>[ ] 20 日（周一）前：开始权益第一轮（10 月 19–25 日这周的开头）。</li></ul>`,31)])])}const b=a(n,[["render",i]]);export{c as __pageData,b as default};
